def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(3))
print(factorial(0))

def order_key(record):
    return (-record[2], record[1])

records = [('r1', 'B', 80), ('r2', 'A', 90), ('r3', 'A', 80), ('r4', 'C', 90), ('r5', 'A', 80)]
ordered = sorted(records, key=order_key)
for record in ordered:
    print(record[0])
